'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var join = require( 'path' ).join;
var logger = require( 'debug' );
var exists = require( '@stdlib/fs/exists' ).sync;
var writeFile = require( '@stdlib/fs/write-file' ).sync;
var pkgNames = require( '@stdlib/_tools/pkgs/names' );
var namespace = require( '@stdlib/namespace' );
var pkg2alias = require( '@stdlib/namespace/pkg2alias' );
var pkg2related = require( '@stdlib/namespace/pkg2related' );


// VARIABLES //

var debug = logger( 'namespace:packages:build' );

// Root of the monorepo lib directory:
var LIB_DIR = resolve( __dirname, '..', '..', '..', '..', '..' );

// Root of the monorepo:
var REPO_ROOT = resolve( LIB_DIR, '..' );

// Prefix stripped from package names in the contributor-facing catalog:
var STDLIB_PREFIX = '@stdlib/';

// Output file paths:
var OUTPUT_JSON = resolve( __dirname, '..', 'data', 'data.json' );
var ROOT_JSON = resolve( REPO_ROOT, 'pkg-catalog.json' );

// Contributor-facing artifacts (meeting decision 2026-04-15: CSV + JSON in `docs/contributing/`, primary columns = name (without `@stdlib/` prefix) + description, plus capability metadata):
var CONTRIB_JSON = resolve( REPO_ROOT, 'docs', 'contributing', 'packages.json' );
var CONTRIB_CSV = resolve( REPO_ROOT, 'docs', 'contributing', 'packages.csv' );


// FUNCTIONS //

/**
* Builds a lookup mapping package paths to their namespace type.
*
* @private
* @returns {Object} mapping from package path to type string
*/
function buildTypeIndex() {
	var entries;
	var out;
	var i;

	entries = namespace();
	out = {};
	for ( i = 0; i < entries.length; i++ ) {
		out[ entries[ i ].path ] = entries[ i ].type;
	}
	return out;
}

/**
* Strips the `@stdlib/` prefix from a package name.
*
* @private
* @param {string} pkg - fully-qualified package name
* @returns {string} package name without the `@stdlib/` prefix
*/
function stripPrefix( pkg ) {
	if ( pkg.indexOf( STDLIB_PREFIX ) === 0 ) {
		return pkg.substring( STDLIB_PREFIX.length );
	}
	return pkg;
}

/**
* Escapes a value for inclusion in a CSV field.
*
* ## Notes
*
* -   Follows RFC 4180: fields containing a comma, double-quote, carriage return, or newline are wrapped in double quotes, and any embedded double quotes are doubled.
*
* @private
* @param {*} value - value to escape
* @returns {string} CSV-safe string
*/
function csvEscape( value ) {
	var str;
	if ( value === null || value === void 0 ) {
		return '';
	}
	str = String( value );
	if ( /[",\r\n]/.test( str ) ) {
		return '"' + str.replace( /"/g, '""' ) + '"';
	}
	return str;
}

/**
* Returns the description for a package by reading its package.json.
*
* @private
* @param {string} pkgDir - absolute path to the package directory
* @returns {string} package description, or empty string if not found
*/
function getDescription( pkgDir ) {
	var pkgJSON;
	var fpath;

	fpath = join( pkgDir, 'package.json' );
	if ( !exists( fpath ) ) {
		return '';
	}
	try {
		pkgJSON = require( fpath ); // eslint-disable-line stdlib/no-dynamic-require
		return pkgJSON.description || '';
	} catch ( err ) {
		debug( 'WARNING: unable to read package.json for %s: %s', pkgDir, err.message );
		return '';
	}
}

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var typeIndex;
	var contribRows;
	var related;
	var relatedStripped;
	var csvLines;
	var pkgDir;
	var names;
	var fopts;
	var alias;
	var entry;
	var json;
	var name;
	var type;
	var pkg;
	var tmp;
	var j;
	var i;

	debug( 'Enumerating all packages...' );
	names = pkgNames.sync();
	debug( 'Found %d packages.', names.length );

	debug( 'Building namespace type index...' );
	typeIndex = buildTypeIndex();

	debug( 'Filtering out internal tooling packages...' );
	tmp = [];
	for ( i = 0; i < names.length; i++ ) {
		if ( names[ i ].indexOf( '@stdlib/_tools' ) === -1 ) {
			tmp.push( names[ i ] );
		}
	}
	names = tmp;
	debug( '%d packages after filtering.', names.length );

	debug( 'Building package catalog...' );
	json = {};
	contribRows = [];
	for ( i = 0; i < names.length; i++ ) {
		pkg = names[ i ];
		pkgDir = join( LIB_DIR, 'node_modules', pkg );

		alias = pkg2alias( pkg );
		related = pkg2related( pkg ) || [];
		type = typeIndex[ pkg ] || '';
		name = stripPrefix( pkg );

		entry = {
			'description': getDescription( pkgDir ),
			'alias': alias || '',
			'type': type,
			'related': related,
			'hasCliTool': exists( join( pkgDir, 'bin', 'cli' ) ),
			'hasNativeAddon': exists( join( pkgDir, 'binding.gyp' ) ),
			'hasWasm': exists( join( pkgDir, 'src', 'main.wasm' ) )
		};
		json[ pkg ] = entry;

		// Contributor-facing record: stripped `name` first, then primary description, then metadata. `related` is stripped of the `@stdlib/` prefix so the contributor-facing file is internally consistent:
		relatedStripped = [];
		for ( j = 0; j < related.length; j++ ) {
			relatedStripped.push( stripPrefix( related[ j ] ) );
		}
		contribRows.push({
			'name': name,
			'description': entry.description,
			'alias': entry.alias,
			'type': entry.type,
			'hasCliTool': entry.hasCliTool,
			'hasNativeAddon': entry.hasNativeAddon,
			'hasWasm': entry.hasWasm,
			'related': relatedStripped
		});
	}

	debug( 'Writing to JSON file...' );
	fopts = {
		'encoding': 'utf8'
	};
	writeFile( OUTPUT_JSON, JSON.stringify( json ) + '\n', fopts );

	debug( 'Writing root-level pkg-catalog.json...' );
	writeFile( ROOT_JSON, JSON.stringify( json, null, '  ' ) + '\n', fopts );

	debug( 'Writing contributor-facing packages.json...' );
	writeFile( CONTRIB_JSON, JSON.stringify( contribRows, null, '  ' ) + '\n', fopts );

	debug( 'Writing contributor-facing packages.csv...' );
	csvLines = [ 'name,description,alias,type,has_cli,has_native_addon,has_wasm,related' ];
	for ( i = 0; i < contribRows.length; i++ ) {
		entry = contribRows[ i ];
		csvLines.push([
			csvEscape( entry.name ),
			csvEscape( entry.description ),
			csvEscape( entry.alias ),
			csvEscape( entry.type ),
			entry.hasCliTool ? 'true' : 'false',
			entry.hasNativeAddon ? 'true' : 'false',
			entry.hasWasm ? 'true' : 'false',
			csvEscape( entry.related.join( ';' ) )
		].join( ',' ));
	}
	writeFile( CONTRIB_CSV, csvLines.join( '\n' ) + '\n', fopts );

	debug( 'Done. Wrote %d entries.', names.length );
	console.log( 'Generated package catalog with %d entries.', names.length ); // eslint-disable-line no-console
}


// MAIN //

main();
